mapper.select:
SELECT id, strategy_id, strategy_desc, rule, create_time, update_time
FROM draw_strategy
WHERE strategy_id = #{strategyId}

SELECT COUNT(*)
FROM draw_record
WHERE strategy_id = #{strategyId} AND user_id = #{userId}

SELECT r.record_id AS recordId, r.award_id AS awardId, r.award_name AS awardName, r.award_type AS awardType, r.level AS level, r.state AS state, r.create_time AS createTime FROM draw_record r WHERE r.user_id = #{userId} AND r.award_type != 'THANKS'
AND r.state IN #{s}
ORDER BY r.create_time DESC, r.id DESC LIMIT #{offset}, #{limit}

mapper.update:
UPDATE draw_record
SET state = #{toState}, update_time = NOW()
WHERE record_id = #{recordId} AND state = #{fromState}
